# ⚡ Quick Sort — Short & Smart Variables
```c
void swp(int *x, int *y) {
    int t = *x; *x = *y; *y = t;
}

int part(int a[], int l, int h) {
    int p = a[h], i = l-1, j;
    for(j = l; j < h; j++)
        if(a[j] < p) swp(&a[++i], &a[j]);
    swp(&a[i+1], &a[h]);
    return i+1;
}

void qSort(int a[], int l, int h) {
