## ✅ Final Merge Sort Code (Best Beginner Version)

```c
#include <stdio.h>

void merge(int arr[], int start, int mid, int end) {
    int i = start;
    int j = mid + 1;
    int index = 0;

    int temp[end - start + 1];  // Temporary array

    // Merge both halves into temp array
    while(i <= mid && j <= end) {
        if(arr[i] <= arr[j])
            temp[index++] = arr[i++];
        else
            temp[index++] = arr[j++];
    }

    // Copy remaining elements from left part
    while(i <= mid)
        temp[index++] = arr[i++];

    // Copy remaining elements from right part
    while(j <= end)
        temp[index++] = arr[j++];

    // Copy sorted values from temp back to arr
    index = 0;
    for(i = start; i <= end; i++) {
        arr[i] = temp[index++];
    }
}

void mergeSort(int arr[], int start, int end) {
    if(start < end) {
        int mid = (start + end) / 2;
        mergeSort(arr, start, mid);
        mergeSort(arr, mid + 1, end);
        merge(arr, start, mid, end);
    }
}

int main() {
    int arr[] = {38, 27, 43, 3, 9, 82, 10};
    int n = sizeof(arr) / sizeof(arr[0]);

    mergeSort(arr, 0, n - 1);

    printf("Sorted Array: ");
    for(int i = 0; i < n; i++)
        printf("%d ", arr[i]);
}
